import {useEffect, useRef, useState} from 'preact/hooks';
import {Field, Notice} from '../../components/ui.jsx';
import {validatedQuery} from '../../../../shared/src/index.js';
import {errorPosition} from './search-state.js';

export function QueryEditor({api, orgId, projectId, value, onChange, inputRef, error}) {
  const [items, setItems] = useState([]);
  const [active, setActive] = useState(-1);
  const [open, setOpen] = useState(false);
  const [caret, setCaret] = useState(value.length);
  const [busy, setBusy] = useState(false);
  const [failure, setFailure] = useState(null);
  const listId = 'query-completions';
  const focused = useRef(false);
  let syntaxError = null;
  try {validatedQuery(value);} catch (invalid) {syntaxError = invalid;}
  const position = errorPosition(error ?? syntaxError);
  useEffect(() => {
    if (!orgId) {setItems([]); setBusy(false); return;}
    let current = true;
    const abort = new AbortController();
    const timer = setTimeout(async () => {
      setBusy(true);
      const params = new URLSearchParams({orgId, q: value, caret: String(Math.min(caret, value.length))});
      if (projectId) params.set('projectId', projectId);
      try {
        const result = await api.get('/search/suggestions?' + params, {signal: abort.signal});
        if (!current) return;
        setItems(result.items);
        setActive(-1);
        setFailure(null);
        setOpen(focused.current && result.items.length > 0);
      } catch (invalid) {
        if (!current || abort.signal.aborted) return;
        setItems([]);
        setFailure(invalid);
      } finally {if (current) setBusy(false);}
    }, 180);
    return () => {current = false; clearTimeout(timer); abort.abort();};
  }, [api, orgId, projectId, value, caret]);
  function complete(item) {
    onChange(item.query);
    setOpen(false);
    setActive(-1);
    const nextCaret = item.start + item.replacement.length;
    setCaret(nextCaret);
    queueMicrotask(() => {
      inputRef.current?.focus();
      inputRef.current?.setSelectionRange(nextCaret, nextCaret);
    });
  }
  function keyboard(event) {
    if (event.key === 'Escape') {setOpen(false); setActive(-1); return;}
    if (!items.length) return;
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setOpen(true);
      setActive(previous => (previous + 1) % items.length);
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      setOpen(true);
      setActive(previous => previous <= 0 ? items.length - 1 : previous - 1);
    } else if ((event.key === 'Enter' || event.key === 'Tab') && open && active >= 0) {
      event.preventDefault();
      complete(items[active]);
    }
  }
  function trackCaret(event) {setCaret(event.currentTarget.selectionStart ?? value.length);}
  return <div className="query-editor">
    <Field label="Query" error={error?.details?.query}>
      <input ref={inputRef} data-testid="search-query" aria-label="Search query" role="combobox"
        aria-autocomplete="list" aria-controls={listId} aria-expanded={open}
        aria-activedescendant={open && active >= 0 ? 'query-option-' + active : undefined}
        aria-describedby="query-editor-help" aria-invalid={Boolean(error)}
        value={value} maxLength={4000} spellCheck={false}
        onInput={event => {onChange(event.currentTarget.value); trackCaret(event);}}
        onSelect={trackCaret} onKeyDown={keyboard}
        onFocus={() => {focused.current = true; setOpen(items.length > 0);}}
        onBlur={() => {focused.current = false; setOpen(false);}}/>
    </Field>
    <p id="query-editor-help">Type a field such as status: for accessible values. Arrow keys choose a suggestion; Enter or Tab inserts it. Escape closes the list.</p>
    {position && <p role={error ? 'alert' : 'status'} className="query-position">
      {error?.message ?? syntaxError?.message} · {position.description}
      <button type="button" onClick={() => {inputRef.current.focus(); inputRef.current.setSelectionRange(position.offset, position.end);}}>Select query position</button>
    </p>}
    {!syntaxError && <p role="status">{value.trim() ? 'Query syntax is valid.' : 'An empty query includes all accessible issues.'}</p>}
    <Notice error={failure}/>
    <p role="status">{busy ? 'Loading suggestions…' : items.length + ' suggestions available'}</p>
    {open && <ul id={listId} role="listbox" aria-label="Query suggestions" className="query-options">
      {items.map((item, index) => <li key={item.replacement} id={'query-option-' + index} role="option" aria-selected={active === index}>
        <button type="button" tabIndex={-1} onMouseDown={event => event.preventDefault()} onClick={() => complete(item)}>
          <strong>{item.label}</strong><span>{item.description}</span>
        </button>
      </li>)}
    </ul>}
    {!open && items.length > 0 && <button type="button" onClick={() => {inputRef.current.focus(); setOpen(true);}}>Show query suggestions</button>}
  </div>;
}

import {useEffect, useRef, useState} from 'preact/hooks';
import {Page, Field, Button, Notice, Empty, Loading, useLoad} from '../../components/ui.jsx';
import {routeLink} from '../../router.js';
import {FilterForm} from './filter-form.jsx';
import {QueryEditor} from './query-editor.jsx';
import {useLiveUpdates} from '../../live.js';
import {searchRequest, searchLocation, appendQueryFilter, nextSearchPage, previousSearchPage} from './search-state.js';

export function Highlight({segments = []}) {
  return <>{segments.map((part, index) => part.match ? <mark key={index}>{part.text}</mark> : <span key={index}>{part.text}</span>)}</>;
}

export function SearchHelp() {
  return <details><summary>Query language and examples</summary>
    <p>Use words for token prefixes, or quotes for an exact phrase. Adjacent terms mean AND. NOT binds before AND, then OR. Parentheses override precedence.</p>
    <ul>
      <li><code>status:active AND assignee:@me</code> · my active issues</li>
      <li><code>project:APP AND (label:bug OR priority&gt;=3)</code> · urgent work</li>
      <li><code>created&gt;2026-01-01 AND updated&lt;2027-01-01</code> · UTC date window</li>
      <li><code>"search index" AND NOT status:done</code> · exact phrase excluding completed work</li>
    </ul>
    <p>Filter values match exact IDs or names; quote names with spaces. Priority ranges from 0 to 4. Dates use YYYY-MM-DD; quote full UTC ISO timestamps.</p>
  </details>;
}

export function SearchPage({api, query, navigate}) {
  const organizations = useLoad(() => api.get('/orgs'), []);
  const [orgId, setOrgId] = useState(query.orgId ?? '');
  const [input, setInput] = useState(query.q ?? '');
  const [projectId, setProjectId] = useState(query.projectId ?? '');
  const [results, setResults] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const [stale, setStale] = useState(false);
  const [history, setHistory] = useState(['']);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState('');
  const inputRef = useRef(null);
  const requestVersion = useRef(0);
  const options = useLoad(() => orgId ? api.get('/filters/options?orgId=' + encodeURIComponent(orgId)) : {teams: [], projects: []}, [orgId]);
  useEffect(() => {
    if (!orgId && organizations.data?.items.length) setOrgId(organizations.data.items[0].id);
  }, [organizations.data]);
  useEffect(() => {
    setOrgId(query.orgId ?? '');
    setInput(query.q ?? '');
    setProjectId(query.projectId ?? '');
    setResults(null);
    setHistory(['']);
    requestVersion.current++;
  }, [query.orgId, query.q, query.projectId]);
  const live = useLiveUpdates({orgId, projectId, enabled: Boolean(orgId), onActivity: () => setStale(true)});
  async function run(event, nextHistory = ['']) {
    event?.preventDefault();
    const version = ++requestVersion.current;
    setBusy(true);
    setError(null);
    setSaved('');
    try {
      const path = searchRequest({orgId, query: input, projectId, cursor: nextHistory.at(-1)});
      const data = await api.get(path);
      if (version !== requestVersion.current) return;
      setResults(data);
      setHistory(nextHistory);
      setStale(false);
    } catch (failure) {if (version === requestVersion.current) {setError(failure); setResults(null);}}
    finally {if (version === requestVersion.current) setBusy(false);}
  }
  return <Page title="Search issues" actions={<a href={routeLink('/filters', {orgId})}>Saved filters</a>}>
    <Notice error={organizations.error ?? options.error}/>
    {organizations.loading ? <Loading/> : !organizations.data?.items.length ? <Empty>Create or join an organization to search its work.</Empty> : <>
      <form onSubmit={run}>
        <div className="search-controls">
          <Field label="Organization"><select value={orgId} onChange={event => {setOrgId(event.currentTarget.value); setProjectId(''); setResults(null);}}>
            <option value="">Choose an organization</option>
            {organizations.data.items.map(org => <option key={org.id} value={org.id}>{org.name}</option>)}
          </select></Field>
          <Field label="Project"><select value={projectId} onChange={event => {setProjectId(event.currentTarget.value); setResults(null);}}>
            <option value="">All accessible projects</option>
            {(options.data?.projects ?? []).map(project => <option key={project.id} value={project.id}>{project.key} · {project.name}</option>)}
          </select></Field>
        </div>
        <QueryEditor api={api} orgId={orgId} projectId={projectId} value={input} onChange={setInput} inputRef={inputRef} error={error}/>
        <div className="actions"><Button busy={busy} disabled={!orgId} type="submit">Search</Button>
          <Button type="button" disabled={!orgId || busy} onClick={() => setSaving(true)}>Save search</Button>
          <Button type="button" onClick={() => {setInput(''); setResults(null); setHistory(['']);}}>Clear</Button></div>
      </form>
      <Notice error={error}/><Notice>{saved}</Notice>
      <SearchHelp/>
      <div className="actions"><span>Live updates: {live.status}</span><Button type="button" onClick={() => live.setPaused(!live.paused)}>{live.paused ? 'Resume updates' : 'Pause updates'}</Button>
        {stale && results && <Button type="button" busy={busy} onClick={run}>Activity changed · refresh search</Button>}
      </div>
      {saving && <FilterForm key={orgId + input} api={api} orgId={orgId} filter={{query: input}} teams={options.data?.teams}
        onCancel={() => setSaving(false)} onSaved={filter => {setSaving(false); setSaved('Saved “' + filter.name + '”.');}}/>}
      {busy && <Loading/>}
      {results && <section aria-label="Search results">
        <h2>{results.total} {results.total === 1 ? 'issue' : 'issues'} found</h2>
        <div className="search-facets">{Object.entries(results.facets ?? {}).map(([field, values]) => <details key={field}>
          <summary>{field}</summary>{values.map(item => <Button key={String(item.value)} onClick={() => {setInput(appendQueryFilter(input, field, item.value)); setResults(null);}}>{String(item.value)} ({item.count})</Button>)}
        </details>)}</div>
        {!results.items.length ? <Empty>No accessible issues match this query. Try fewer filters or a shorter token prefix.</Empty> : <ol className="search-results">{results.items.map(issue => <li key={issue.id} data-testid={'search-result-' + issue.id}>
          <article><h3><a href={routeLink('/issues/' + issue.id)}>{issue.key} · <Highlight segments={issue.highlights.title}/></a></h3>
            <p><Highlight segments={issue.highlights.description}/></p>
            {issue.matchFields.includes('comments') && <p className="search-comment">Discussion: <Highlight segments={issue.highlights.comments}/></p>}
            <p>{issue.statusName} · priority {issue.priority} · {issue.assignee?.name ?? 'Unassigned'} · updated {new Date(issue.updatedAt).toLocaleString()}</p>
            <p>{issue.labels.map(label => <span className="label" key={label.id}>{label.name}</span>)}</p>
          </article>
        </li>)}</ol>}
        <div className="actions"><Button disabled={busy || history.length < 2} onClick={event => run(event, previousSearchPage(history))}>Previous</Button>
          <span>Page {history.length}</span><Button disabled={busy || !results.nextCursor} onClick={event => run(event, nextSearchPage(history, results.nextCursor))}>Next</Button></div>
        <a href={'#' + searchLocation(orgId, input, projectId)}>Link to this query</a>
      </section>}
    </>}
  </Page>;
}

.search-controls { display: flex; flex-wrap: wrap; align-items: end; gap: 1rem; }
.search-controls .field { min-width: 15rem; flex: 1; }
.query-suggestions { padding: 1rem; margin: 1rem 0; border: 1px solid #cbd5e1; border-radius: .5rem; }
.query-suggestions h2 { font-size: 1rem; }
.query-suggestions ul { display: flex; flex-wrap: wrap; gap: .5rem 1rem; list-style: none; padding: 0; }
.search-results, .saved-filters { list-style: none; padding: 0; }
.search-results article, .saved-filters article { padding: 1rem 0; border-bottom: 1px solid #cbd5e1; }
.search-results h3 { margin: 0 0 .5rem; }
.search-results mark { background: #fef08a; color: #111827; border-radius: .15rem; }
.search-results p { white-space: pre-wrap; overflow-wrap: anywhere; }
.search-facets { display: flex; gap: 1rem; flex-wrap: wrap; }
.search-comment { font-size: .9rem; color: #475569; }
.filter-form { margin: 1rem 0; padding: 1.25rem; border: 1px solid #cbd5e1; border-radius: .5rem; max-width: 50rem; }
.filter-form textarea { min-height: 5rem; width: 100%; }
.saved-filters pre { white-space: pre-wrap; overflow-wrap: anywhere; }

.query-editor { position: relative; }
.query-options { padding: .25rem; margin: 0 0 1rem; list-style: none; border: 1px solid #64748b; border-radius: .4rem; max-height: 20rem; overflow-y: auto; background: white; }
.query-options button { width: 100%; text-align: left; border: 0; background: transparent; padding: .6rem; display: flex; flex-wrap: wrap; gap: .7rem; color: #0f172a; }
.query-options li[aria-selected="true"] button { background: #dbeafe; }
.query-options span { font-size: .85rem; color: #475569; }
.query-position { color: #9a3412; }
